import { readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

const root = import.meta.dirname

// Every posts/**/index.html (generated by scripts/build-post-pages.mjs) is its
// own page with its own <head>, so link previews show the post, not the CV.
const postPages = Object.fromEntries(
  readdirSync(resolve(root, 'posts'), { recursive: true })
    .map(String)
    .filter((file) => file.endsWith('index.html'))
    .map((file) => [
      `posts/${file}`.replace(/\/?index\.html$/, ''),
      resolve(root, 'posts', file),
    ]),
)

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
  build: {
    rollupOptions: {
      input: {
        main: resolve(root, 'index.html'),
        ...postPages,
      },
    },
  },
})
